void dei_rf1_ext_enable_falling (void)
{    
	CRITICAL;


	C_ENTER;
	{ 
		#ifdef DEV_LPC_236x
		VICIntEnClr |= (1u << ISR_ID_EINT_1) ;
		#endif
		
		EXTPOLAR&=~(1u<<1); 
		
		EXTINT  |= (1u<<1);

		#ifdef DEV_LPC_236x
		VICIntEnable |= (1u << ISR_ID_EINT_1) ;
		#endif
	}
	C_LEAVE;      
} 


//---------------------------------------------------------------------------//

void dei_rf1_ext_enable_rising (void)
{    
	CRITICAL ;

	C_ENTER;
	{ 
		EXTPOLAR|=(1u<<1); 
		
		EXTINT  |= (1u<<1);

		#ifdef DEV_LPC_236x
		VICIntEnable |= (1u << ISR_ID_EINT_1) ;
		#endif
	}
	C_LEAVE;          
} 


